import type { CalculatorLocale } from "./types";

export type BilingualText = Readonly<Record<CalculatorLocale, string>>;

export type ConstructionBuildingGroupKey = "core" | "military" | "economy";

export interface ConstructionAttributeDef {
  readonly id: number;
  readonly vi: string;
  readonly en: string;
  readonly isPercent: boolean;
}

/**
 * Compact tuple for each building level row from `citybuilding_lvup_new`:
 * [0] lv
 * [1] fightforce (Uy Thế at level lv)
 * [2] buildTime (Base seconds to upgrade lv -> lv + 1)
 * [3] shineLv (Brilliance tier 0..8)
 * [4] subSteps (1 for Lv.1..39, 5 for Lv.40+ Brilliance sub-steps)
 * [5] [timber, stone, ruby, dragonEssence] (Base costs for 1 sub-step)
 * [6] [[preBuildingId, requiredLv], ...] (Standard prerequisites)
 * [7] [[preBuildingId, requiredLv], ...] (New server prerequisites)
 * [8] [[attrId, value], ...] (Attributes active at level lv)
 */
export type CompactBuildingLevelTuple = readonly [
  number,
  number,
  number,
  number,
  number,
  readonly [number, number, number, number],
  readonly (readonly [number, number])[],
  readonly (readonly [number, number])[],
  readonly (readonly [number, number])[],
];

export interface ConstructionBuildingDef {
  readonly id: number;
  readonly slug: string;
  readonly group: ConstructionBuildingGroupKey;
  readonly icon: string;
  readonly name: BilingualText;
  readonly description: BilingualText;
  readonly maxLevel: number;
  readonly levels: readonly CompactBuildingLevelTuple[];
}

export interface ConstructionGlobalBuffs {
  readonly freeMinutes: number;
  readonly privilegeMinutes: number;
  readonly speedBonusPct: number;
  readonly costReductionPct: number;
}

export interface ConstructionWarehouseState {
  readonly timber: number | null;
  readonly stone: number | null;
  readonly ruby: number | null;
  readonly dragonEssence: number | null;
}

export interface ConstructionQueueState {
  readonly queueId: string;
  readonly buildingId: number;
  readonly fromLevel: number;
  readonly toLevel: number;
  readonly multiplyBrillianceSubSteps: boolean;
  readonly useNewServerPrerequisites: boolean;
}

export interface ConstructionResourceBreakdown {
  readonly timber: number;
  readonly stone: number;
  readonly ruby: number;
  readonly dragonEssence: number;
}

export interface ConstructionAttributeGain {
  readonly attrId: number;
  readonly label: BilingualText;
  readonly isPercent: boolean;
  readonly currentValue: number;
  readonly targetValue: number;
  readonly deltaValue: number;
}

export interface ConstructionPrerequisiteItem {
  readonly buildingId: number;
  readonly buildingName: BilingualText;
  readonly buildingIcon: string;
  readonly requiredLevel: number;
}

export interface ConstructionQueueResourceStatus {
  readonly key: keyof ConstructionResourceBreakdown;
  readonly label: BilingualText;
  readonly icon: string;
  readonly baseRequired: number;
  readonly required: number;
  readonly owned: number | null;
  readonly isSufficient: boolean | null;
  readonly deficit: number;
}

export interface ConstructionQueuePlan {
  readonly queueId: string;
  readonly building: ConstructionBuildingDef;
  readonly fromLevel: number;
  readonly toLevel: number;
  readonly currentFightforce: number;
  readonly targetFightforce: number;
  readonly deltaFightforce: number;
  readonly attributeGains: readonly ConstructionAttributeGain[];
  readonly prerequisites: readonly ConstructionPrerequisiteItem[];
  readonly baseCosts: ConstructionResourceBreakdown;
  readonly discountedCosts: ConstructionResourceBreakdown;
  readonly resourceStatuses: readonly ConstructionQueueResourceStatus[];
  readonly baseTimeSeconds: number;
  readonly effectiveTimeSeconds: number;
  readonly savedTimeSeconds: number;
  readonly instantDiamonds: number;
  readonly totalStepsCount: number;
  readonly hasBrillianceSteps: boolean;
}

export interface ConstructionGlobalSummary {
  readonly queueCount: number;
  readonly totalDeltaFightforce: number;
  readonly totalDiscountedCosts: ConstructionResourceBreakdown;
  readonly totalDeficits: ConstructionResourceBreakdown;
  readonly parallelTimeSeconds: number;
  readonly totalSpeedupTimeSeconds: number;
  readonly totalBaseTimeSeconds: number;
  readonly totalInstantDiamonds: number;
}

