const BUILDING_BY_ID = new Map<number, ConstructionBuildingDef>(
  CONSTRUCTION_BUILDINGS.map((b) => [b.id, b])
);

export function getBuildingById(buildingId: number): ConstructionBuildingDef {
  return BUILDING_BY_ID.get(buildingId) ?? CONSTRUCTION_BUILDINGS[0]!;
}

/**
 * Formats numbers using in-game 3-significant-digit truncation (e.g., 34,960,000 -> "34.9M", 1,909,500 -> "1.90M").
 */
export function formatGameResourceCompact(value: number): string {
  const safe = Math.max(0, Math.floor(value));
  if (safe >= 1_000_000_000) {
    const b = safe / 1_000_000_000;
    if (b >= 100) return `${Math.floor(b)}B`;
    if (b >= 10) return `${(Math.floor(b * 10) / 10).toFixed(1)}B`;
    return `${(Math.floor(b * 100) / 100).toFixed(2)}B`;
  }
  if (safe >= 1_000_000) {
    const m = safe / 1_000_000;
    if (m >= 100) return `${Math.floor(m)}M`;
    if (m >= 10) return `${(Math.floor(m * 10) / 10).toFixed(1)}M`;
    return `${(Math.floor(m * 100) / 100).toFixed(2)}M`;
  }
  if (safe >= 10_000) {
    const k = safe / 1_000;
    if (k >= 100) return `${Math.floor(k)}K`;
    return `${(Math.floor(k * 10) / 10).toFixed(1)}K`;
  }
  return safe.toLocaleString("en-US");
}

/**
 * Formats seconds into in-game timer string (e.g., 253638 -> "2Ngày 22:27:18" or "2d 22:27:18").
 */
export function formatBuildDuration(totalSeconds: number, locale: "vi" | "en"): string {
  const safe = Math.max(0, Math.floor(totalSeconds));
  if (safe === 0) {
    return locale === "vi" ? "00:00:00" : "00:00:00";
  }
  const days = Math.floor(safe / 86400);
  const hours = Math.floor((safe % 86400) / 3600);
  const minutes = Math.floor((safe % 3600) / 60);
  const seconds = safe % 60;
  const hh = String(hours).padStart(2, "0");
  const mm = String(minutes).padStart(2, "0");
  const ss = String(seconds).padStart(2, "0");
  if (days > 0) {
    return locale === "vi" ? `${days}Ngày ${hh}:${mm}:${ss}` : `${days}d ${hh}:${mm}:${ss}`;
  }
  return `${hh}:${mm}:${ss}`;
}

export function formatAttributeValue(value: number, isPercent: boolean): string {
  if (!isPercent) {
    return value.toLocaleString("en-US");
  }
  const pct = value / 100;
  return Number.isInteger(pct) ? `${pct}%` : `${pct.toFixed(1).replace(/\.0$/, "")}%`;
}

export function formatBuildingLevelBadge(level: number, locale: "vi" | "en"): string {
  if (level <= 40) {
    return `Lv.${level}`;
  }
  const brillianceTier = Math.ceil((level - 40) / 5);
  return locale === "vi"
    ? `Lv.${level} (HH ${brillianceTier})`
    : `Lv.${level} (Brilliance ${brillianceTier})`;
}

export function computeQueueUpgradePlan(
  queue: ConstructionQueueState,
  buffs: ConstructionGlobalBuffs,
  warehouse: ConstructionWarehouseState
): ConstructionQueuePlan {
  const building = getBuildingById(queue.buildingId);
  const clampedFrom = Math.max(1, Math.min(building.maxLevel - 1, Math.floor(queue.fromLevel)));
  const clampedTo = Math.max(clampedFrom + 1, Math.min(building.maxLevel, Math.floor(queue.toLevel)));

  const levelMap = new Map<number, CompactBuildingLevelTuple>();
  for (const row of building.levels) {
    levelMap.set(row[0], row);
  }

  const fromRow = levelMap.get(clampedFrom) ?? building.levels[0]!;
  const toRow = levelMap.get(clampedTo) ?? building.levels[building.levels.length - 1]!;

  const currentFightforce = fromRow[1];
  const targetFightforce = toRow[1];
  const deltaFightforce = Math.max(0, targetFightforce - currentFightforce);

  // Compute attribute gains between fromRow and toRow
  const fromAttrs = new Map<number, number>(fromRow[8]);
  const toAttrs = new Map<number, number>(toRow[8]);
  const allAttrIds = new Set<number>([...fromAttrs.keys(), ...toAttrs.keys()]);

  const attributeGains: ConstructionAttributeGain[] = [];
  for (const attrId of allAttrIds) {
    const curVal = fromAttrs.get(attrId) ?? 0;
    const tarVal = toAttrs.get(attrId) ?? curVal;
    const deltaVal = tarVal - curVal;
    const def = CONSTRUCTION_ATTRIBUTES[attrId];
    if (!def) continue;
    // Prioritize attributes that increase in this upgrade range, or show primary attributes if none change
    if (deltaVal > 0 || allAttrIds.size <= 2) {
      attributeGains.push({
        attrId,
        label: { vi: def.vi, en: def.en },
        isPercent: def.isPercent,
        currentValue: curVal,
        targetValue: tarVal,
        deltaValue: Math.max(0, deltaVal),
      });
    }
  }

  // Fallback if no attribute had delta > 0 on a multi-attribute building
  if (attributeGains.length === 0) {
    for (const [attrId, curVal] of fromRow[8].slice(0, 2)) {
      const def = CONSTRUCTION_ATTRIBUTES[attrId];
      if (!def) continue;
      const tarVal = toAttrs.get(attrId) ?? curVal;
      attributeGains.push({
        attrId,
        label: { vi: def.vi, en: def.en },
        isPercent: def.isPercent,
        currentValue: curVal,
        targetValue: tarVal,
        deltaValue: Math.max(0, tarVal - curVal),
      });
    }
  }

  // Aggregate costs, prerequisites, and build times across lv = clampedFrom .. clampedTo - 1
  let baseTimber = 0;
  let baseStone = 0;
  let baseRuby = 0;
  let baseDragonEssence = 0;
  let discTimber = 0;
  let discStone = 0;
  let discRuby = 0;
  let discDragonEssence = 0;
  let baseTimeSeconds = 0;
  let effectiveTimeSeconds = 0;
  let totalStepsCount = 0;
  let hasBrillianceSteps = false;

  const prereqMaxByBuilding = new Map<number, number>();
  const discountFactor = Math.max(0, 1 - Math.max(0, Math.min(80, buffs.costReductionPct)) / 100);
  const speedDivisor = 1 + Math.max(0, buffs.speedBonusPct) / 100;
  const freeSecondsPerStep = Math.max(0, buffs.freeMinutes + buffs.privilegeMinutes) * 60;

  for (let lv = clampedFrom; lv < clampedTo; lv++) {
    const stepRow = levelMap.get(lv);
    if (!stepRow) continue;

    const rawSubSteps = stepRow[4];
    if (rawSubSteps > 1) {
      hasBrillianceSteps = true;
    }
    const multiplier = queue.multiplyBrillianceSubSteps ? rawSubSteps : 1;
    totalStepsCount += multiplier;

    const [t, s, r, de] = stepRow[5];
    baseTimber += t * multiplier;
    baseStone += s * multiplier;
    baseRuby += r * multiplier;
    baseDragonEssence += de * multiplier;

    discTimber += Math.floor(t * discountFactor) * multiplier;
    discStone += Math.floor(s * discountFactor) * multiplier;
    discRuby += Math.floor(r * discountFactor) * multiplier;
    // Dragon essence is not reduced by Timber/Stone/Ruby tool discount
    discDragonEssence += de * multiplier;

    const stepBaseTime = stepRow[2];
    baseTimeSeconds += stepBaseTime * multiplier;

    const stepAfterSpeed = Math.floor(stepBaseTime / speedDivisor);
    const stepEffective = Math.max(0, stepAfterSpeed - freeSecondsPerStep);
    effectiveTimeSeconds += stepEffective * multiplier;

    const preList = queue.useNewServerPrerequisites ? stepRow[7] : stepRow[6];
    for (const [preBid, preLv] of preList) {
      const prevMax = prereqMaxByBuilding.get(preBid) ?? 0;
      if (preLv > prevMax) {
        prereqMaxByBuilding.set(preBid, preLv);
      }
    }
  }

  const prerequisites: ConstructionPrerequisiteItem[] = Array.from(prereqMaxByBuilding.entries()).map(
    ([preBid, reqLv]) => {
      const preB = getBuildingById(preBid);
      return {
        buildingId: preBid,
        buildingName: preB.name,
        buildingIcon: preB.icon,
        requiredLevel: reqLv,
      };
    }
  );

  const baseCosts: ConstructionResourceBreakdown = {
    timber: baseTimber,
    stone: baseStone,
    ruby: baseRuby,
    dragonEssence: baseDragonEssence,
  };

  const discountedCosts: ConstructionResourceBreakdown = {
    timber: discTimber,
    stone: discStone,
    ruby: discRuby,
    dragonEssence: discDragonEssence,
  };

  // Order resources matching the user's screenshot: Timber, Ruby, Stone, and Dragon Essence (if > 0)
  const orderedKeys: (keyof ConstructionResourceBreakdown)[] =
    discDragonEssence > 0
      ? ["timber", "ruby", "stone", "dragonEssence"]
      : ["timber", "ruby", "stone"];

  const resourceStatuses: ConstructionQueueResourceStatus[] = orderedKeys
    .filter((key) => discountedCosts[key] > 0 || key !== "dragonEssence")
    .map((key) => {
      const metaRes = CONSTRUCTION_RESOURCE_META[key];
      const req = discountedCosts[key];
      const owned = warehouse[key];
      const isSufficient = owned === null ? null : owned >= req;
      const deficit = owned === null ? req : Math.max(0, req - owned);
      return {
        key,
        label: metaRes.label,
        icon: metaRes.icon,
        baseRequired: baseCosts[key],
        required: req,
        owned,
        isSufficient,
        deficit,
      };
    });

  const instantDiamonds = effectiveTimeSeconds > 0 ? Math.ceil(effectiveTimeSeconds / 3) : 0;

  return {
    queueId: queue.queueId,
    building,
    fromLevel: clampedFrom,
    toLevel: clampedTo,
    currentFightforce,
    targetFightforce,
    deltaFightforce,
    attributeGains,
    prerequisites,
    baseCosts,
    discountedCosts,
    resourceStatuses,
    baseTimeSeconds,
    effectiveTimeSeconds,
    savedTimeSeconds: Math.max(0, baseTimeSeconds - effectiveTimeSeconds),
    instantDiamonds,
    totalStepsCount,
    hasBrillianceSteps,
  };
}

export function aggregateConstructionQueues(
  plans: readonly ConstructionQueuePlan[],
  warehouse: ConstructionWarehouseState
): ConstructionGlobalSummary {
  let totalDeltaFightforce = 0;
  let timber = 0;
  let stone = 0;
  let ruby = 0;
  let dragonEssence = 0;
  let parallelTimeSeconds = 0;
  let totalSpeedupTimeSeconds = 0;
  let totalBaseTimeSeconds = 0;
  let totalInstantDiamonds = 0;

  for (const p of plans) {
    totalDeltaFightforce += p.deltaFightforce;
    timber += p.discountedCosts.timber;
    stone += p.discountedCosts.stone;
    ruby += p.discountedCosts.ruby;
    dragonEssence += p.discountedCosts.dragonEssence;
    if (p.effectiveTimeSeconds > parallelTimeSeconds) {
      parallelTimeSeconds = p.effectiveTimeSeconds;
    }
    totalSpeedupTimeSeconds += p.effectiveTimeSeconds;
    totalBaseTimeSeconds += p.baseTimeSeconds;
    totalInstantDiamonds += p.instantDiamonds;
  }

  return {
    queueCount: plans.length,
    totalDeltaFightforce,
    totalDiscountedCosts: { timber, stone, ruby, dragonEssence },
    totalDeficits: {
      timber: warehouse.timber === null ? timber : Math.max(0, timber - warehouse.timber),
      stone: warehouse.stone === null ? stone : Math.max(0, stone - warehouse.stone),
      ruby: warehouse.ruby === null ? ruby : Math.max(0, ruby - warehouse.ruby),
      dragonEssence:
        warehouse.dragonEssence === null
          ? dragonEssence
          : Math.max(0, dragonEssence - warehouse.dragonEssence),
    },
    parallelTimeSeconds,
    totalSpeedupTimeSeconds,
    totalBaseTimeSeconds,
    totalInstantDiamonds,
  };
}
